const dashState={target:10000,range:'month',start:'',end:'',tasks:[],meetings:[],reminders:[],nps:[],activities:[],showPanels:true,dialog:null,editingId:null};
const dashCurrency=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const dashToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dashStamp=()=>new Date().toLocaleString('pt-BR');
function dashClients(){return clientsState.items.filter(c=>!c.archived)}
function dashEarned(date){return dashClients().reduce((sum,c)=>{if(!c.start||!Number(c.months))return sum;const start=new Date(c.start+'T12:00:00'),end=new Date(start);end.setMonth(end.getMonth()+Number(c.months));return date>=start&&date<end?sum+(Number(c.monthly)||0):sum},0)}
function dashPeriod(){const now=new Date(),start=dashState.start?new Date(dashState.start+'T00:00:00'):new Date(now.getFullYear(),now.getMonth(),1),end=dashState.end?new Date(dashState.end+'T23:59:59'):new Date(now.getFullYear(),now.getMonth()+1,0,23,59,59);return {start,end}}
function dashInPeriod(date){if(!date)return false;const {start,end}=dashPeriod(),d=new Date(date+'T12:00:00');return d>=start&&d<=end}
function dashValues(){const {start,end}=dashPeriod();let total=0,days=0;for(let d=new Date(start.getFullYear(),start.getMonth(),start.getDate());d<=end&&days<3660;d.setDate(d.getDate()+1)){const monthDays=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();total+=dashEarned(new Date(d.getFullYear(),d.getMonth(),d.getDate(),12))/monthDays;days++}return {total,newClients:dashClients().filter(c=>dashInPeriod(c.start)).length,closed:dashClients().filter(c=>c.stage==='Fechado').length,days}}
function dashLine(){const now=new Date(),points=Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,15);return {label:d.toLocaleString('pt-BR',{month:'long',year:'numeric'}),short:d.toLocaleString('pt-BR',{month:'short'}),value:dashEarned(d)}});const max=Math.max(1000,...points.map(p=>p.value))*1.2,coords=points.map((p,i)=>({x:35+i*125,y:210-p.value/max*175})),area=`M ${coords[0].x},${coords[0].y} L ${coords.slice(1).map(p=>`${p.x},${p.y}`).join(' L ')} L 660,210 L 35,210 Z`;return `<div class="dash-chart-wrap"><svg role="img" aria-label="Faturamento mensal estimado dos últimos seis meses. Passe o mouse ou use Tab para ver cada mês." viewBox="0 0 700 240" preserveAspectRatio="none"><defs><linearGradient id="dash-gradient" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ff6400" stop-opacity=".4"/><stop offset="1" stop-color="#ff6400" stop-opacity=".02"/></linearGradient></defs><path d="M35 35H660M35 95H660M35 155H660M35 210H660" stroke="#34425a" stroke-dasharray="3 5"/><path d="${area}" fill="url(#dash-gradient)"/><polyline points="${coords.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="#ff6400" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<g class="dash-chart-point" tabindex="0" role="img" aria-label="${esc(p.label)}: ${dashCurrency(p.value)}" data-label="${esc(p.label)}" data-value="${dashCurrency(p.value)}"><circle cx="${coords[i].x}" cy="${coords[i].y}" r="5" fill="#ff6400"/><circle cx="${coords[i].x}" cy="${coords[i].y}" r="19" fill="transparent"/><title>${esc(p.label)}: ${dashCurrency(p.value)} (estimativa de contratos)</title></g>`).join('')}</svg><div class="dash-chart-tooltip" id="dash-chart-tooltip" hidden></div></div><div class="chart-labels">${points.map(p=>`<span>${esc(p.short)}</span>`).join('')}</div>`}
function dashList(items,fn,empty){return items.length?`<ul class="dash-list">${items.map(fn).join('')}</ul>`:`<div class="dash-empty">${empty}</div>`}
function dashTaskRow(t,compact=false){return `<li class="dash-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.client||'Sem cliente')}${t.responsible?' · '+esc(t.responsible):''}${t.due?' · '+formatDate(t.due):''}${t.time?' às '+esc(t.time):''}</small></div><div class="dash-row-actions"><button data-dash="edit-task" data-id="${esc(t.id)}">Editar</button><button data-dash="complete" data-id="${esc(t.id)}">Concluir</button></div></li>`}
function dashMeetingRow(m){return `<li class="dash-row"><div><strong>${esc(m.title)}</strong><small>${formatDate(m.date)} às ${esc(m.time)} · ${esc(m.client||'Sem cliente')}</small><small>Responsável: ${esc(m.responsible)}${m.location?' · '+esc(m.location):''}</small></div><div class="dash-row-actions"><button data-dash="edit-meeting" data-id="${esc(m.id)}">Editar</button><button data-dash="cancel-meeting" data-id="${esc(m.id)}">Cancelar</button></div></li>`}
function dashActivity(text,clientId){dashState.activities.unshift({text,date:dashStamp(),timestamp:new Date().toISOString(),clientId:clientId||null})}
function renderDashboard(){const w=document.querySelector('.workspace');w.classList.remove('clients-mode','technical-mode','kanban-mode','pipeline-mode');w.classList.add('dashboard-mode');document.querySelector('#page-title').textContent='Dashboard';const v=dashValues(),pct=Math.min(100,Math.round(v.total/Math.max(1,dashState.target)*100)),today=dashToday(),tasks=dashState.tasks.filter(t=>!t.archived),overdue=tasks.filter(t=>!t.done&&t.due&&t.due<today),due=tasks.filter(t=>!t.done&&t.due===today),meetings=dashState.meetings.filter(m=>!m.cancelled&&m.date>=today).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),services=new Map();dashClients().forEach(c=>{if(c.project)services.set(c.project,(services.get(c.project)||0)+(Number(c.monthly)||0))});const serviceRows=[...services].sort((a,b)=>b[1]-a[1]),serviceSum=serviceRows.reduce((n,x)=>n+x[1],0),maxService=Math.max(1,...serviceRows.map(s=>s[1])),scores=dashState.nps.map(x=>Number(x.score)),nps=scores.length?Math.round((scores.filter(x=>x>=9).length-scores.filter(x=>x<=6).length)/scores.length*100):0;w.innerHTML=`<div class="dash-wrap"><div class="dash-head"><div><h2>Dashboard</h2><p>Visão geral do seu negócio · estimativas baseadas nos cadastros desta sessão</p></div><div class="dash-controls"><select id="dash-range" aria-label="Filtros rápidos"><option value="month" ${dashState.range==='month'?'selected':''}>Este mês</option><option value="7" ${dashState.range==='7'?'selected':''}>Últimos 7 dias</option><option value="30" ${dashState.range==='30'?'selected':''}>Últimos 30 dias</option><option value="custom" ${dashState.range==='custom'?'selected':''}>Período personalizado</option></select><input id="dash-start" type="date" aria-label="Data inicial" value="${dashState.start}"/><span>–</span><input id="dash-end" type="date" aria-label="Data final" value="${dashState.end}"/><button class="dash-btn" data-dash="panels">${dashState.showPanels?'Ocultar':'Mostrar'} painéis</button><button class="dash-btn" data-dash="goal">Editar meta</button></div></div><div class="dash-top"><div class="dash-card"><div class="dash-card-head"><h3>Meta de Receita</h3><span class="accent">◎</span></div><p>Estimativa para o período selecionado</p><div class="dash-meta"><span>${dashCurrency(v.total)}</span><strong class="accent">${dashCurrency(dashState.target)}</strong></div><div class="dash-progress" style="--progress:${pct}%"><i></i></div><div class="dash-meta"><span>${pct}% da meta</span><span>Faltam ${dashCurrency(Math.max(0,dashState.target-v.total))}</span></div></div><div class="dash-card"><h3>＄</h3><div class="big positive">${dashCurrency(v.total)}</div><p>Receita contratual estimada no período</p></div><div class="dash-card"><h3>♧</h3><div class="big">${v.newClients}</div><p>Novos clientes no período</p></div><div class="dash-card"><h3>↗</h3><div class="big accent">${v.closed}</div><p>Clientes fechados</p></div></div><section class="dash-card dash-chart"><div class="dash-card-head"><div><h3>Análise Financeira Consolidada</h3><p>Receita contratual mensal estimada · últimos 6 meses</p></div><button class="dash-btn" data-dash="finance">Ver clientes</button></div>${dashLine()}</section><div id="dash-panels" ${dashState.showPanels?'':'hidden'}><div class="dash-grid two"><section class="dash-card"><h3>Receita por serviço</h3>${serviceRows.length?serviceRows.map(([name,n])=>`<div class="dash-service-row"><span title="${esc(name)}">${esc(name)}</span><span class="bar" style="--bar:${Math.round(n/maxService*100)}%"><i></i></span><b>${dashCurrency(n)}</b></div>`).join(''):'<div class="dash-empty">Nenhum serviço vinculado</div>'}</section><section class="dash-card"><h3>Composição da carteira</h3>${dashList(serviceRows,([name,n])=>`<li class="dash-row"><span>${esc(name)}</span><b>${Math.round(n/Math.max(1,serviceSum)*100)}%</b></li>`,'Nenhum cliente ativo')}</section></div><div class="dash-grid"><section class="dash-card"><div class="dash-card-head"><h3>Tarefas Diárias</h3><button class="dash-btn" data-dash="task">＋ Criar tarefa</button></div>${dashList(due,dashTaskRow,'Nenhuma tarefa para hoje')}</section><section class="dash-card"><h3>Projetos Recentes</h3>${dashList(projectStore.projects.filter(p=>!p.archived).slice(-5).reverse(),p=>`<li><button data-dash="client" data-id="${esc(p.clientId)}">${esc(p.name)}</button><small>${esc(dashClients().find(c=>c.id===p.clientId)?.name||'Cliente não encontrado')} · ${esc(p.status)}</small></li>`,'Nenhum projeto cadastrado')}</section><section class="dash-card"><h3>Atividade Recente</h3>${dashList(dashState.activities.slice(0,8),a=>`<li>${esc(a.text)}<small>${esc(a.date)}</small></li>`,'As ações realizadas aparecerão aqui')}</section></div><div class="dash-grid"><section class="dash-card"><div class="dash-card-head"><h3>Tarefas Atrasadas</h3><b class="accent">${overdue.length}</b></div>${dashList(overdue,dashTaskRow,'Nenhuma tarefa atrasada')}</section><section class="dash-card"><h3>Tarefas para Hoje</h3>${dashList(due,dashTaskRow,'Nenhuma tarefa para hoje')}<button class="dash-btn" data-dash="all-tasks">Ver todas →</button></section><section class="dash-card"><h3>Lembretes Rápidos</h3><form id="reminder-form" class="dash-input-row"><input name="reminder" maxlength="120" required placeholder="Adicionar lembrete..." aria-label="Adicionar lembrete"><button class="dash-btn orange" aria-label="Salvar lembrete">＋</button></form>${dashList(dashState.reminders,r=>`<li class="dash-row"><span>${esc(r.text)}</span><button data-dash="remove-reminder" data-id="${esc(r.id)}" aria-label="Excluir lembrete">×</button></li>`,'Nenhum lembrete ainda')}</section></div><div class="dash-grid"><section class="dash-card"><div class="dash-card-head"><h3>Próximas Reuniões</h3><button class="dash-btn" data-dash="meeting">＋ Agendar</button></div>${dashList(meetings,dashMeetingRow,'Nenhuma reunião agendada')}<button class="dash-btn" data-dash="all-meetings">Ver agenda →</button></section><section class="dash-card"><h3>Estoque Baixo</h3><div class="dash-empty">Estoque sem produtos cadastrados</div><button class="dash-btn" data-dash="products">Ver produtos</button></section><section class="dash-card"><h3>Conteúdos do Dia</h3><div class="dash-empty">Nenhum conteúdo programado</div><button class="dash-btn" data-dash="content">Ver calendário</button></section></div><div class="dash-grid two"><section class="dash-card"><h3>Saúde de Relacionamento</h3><p>Clientes sem reunião registrada</p>${dashList(dashClients().filter(c=>!dashState.meetings.some(m=>m.clientId===c.id&&!m.cancelled)),c=>`<li class="dash-row"><button data-dash="client" data-id="${esc(c.id)}">${esc(c.name)}</button><span class="accent">Sem reunião</span></li>`,'Todos os clientes têm reunião registrada')}</section><section class="dash-card"><div class="dash-card-head"><h3>Saúde dos Clientes (NPS)</h3><button class="dash-btn" data-dash="nps">＋ Registrar</button></div><div class="dash-nps"><div>NPS<b>${scores.length?nps:'—'}</b></div><div>Promotores<b>${scores.filter(x=>x>=9).length}</b></div><div>Neutros<b>${scores.filter(x=>x>=7&&x<=8).length}</b></div><div>Detratores<b>${scores.filter(x=>x<=6).length}</b></div></div>${dashList(dashState.nps.slice().reverse().slice(0,4),x=>`<li>${esc(dashClients().find(c=>c.id===x.clientId)?.name||'Cliente')} · nota ${x.score}<small>${esc(x.date)}</small></li>`,'Registre uma avaliação para começar')}</section></div><section class="dash-card" style="text-align:center;margin-top:15px;padding:35px"><h3>Diagnóstico do negócio</h3><p>Resumo baseado nos clientes, contratos e tarefas cadastrados nesta sessão.</p><button class="dash-btn orange" data-dash="diagnosis">Gerar diagnóstico</button><div id="dash-diagnosis"></div></section></div></div>`;if(typeof refreshGlobalBar==='function')refreshGlobalBar()}
function dashClientOptions(selected=''){return `<option value="">Sem cliente</option>${dashClients().map(c=>`<option value="${esc(c.id)}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}`}
function dashOpen(kind,id=''){dashState.dialog=kind;dashState.editingId=id;document.querySelector('.dash-dialog')?.remove();const task=dashState.tasks.find(t=>t.id===id),meeting=dashState.meetings.find(m=>m.id===id);let content='';if(kind==='goal')content=`<label>Meta para o período (R$)<input name="value" type="number" min="1" step="0.01" required value="${dashState.target}"></label>`;if(kind==='task')content=`<label>Descrição da tarefa<input name="title" required maxlength="120" value="${esc(task?.title)}"></label><div class="dash-form-grid"><label>Data de vencimento<input name="due" type="date" required value="${esc(task?.due||dashToday())}"></label><label>Horário (opcional)<input name="time" type="time" value="${esc(task?.time)}"></label></div><label>Cliente<select name="clientId">${dashClientOptions(task?.clientId)}</select></label><label>Responsável<input name="responsible" maxlength="80" value="${esc(task?.responsible)}" placeholder="Nome do responsável"></label><label>Detalhes<textarea name="notes" rows="3">${esc(task?.notes)}</textarea></label>`;if(kind==='meeting')content=`<label>Assunto da reunião<input name="title" required maxlength="120" value="${esc(meeting?.title)}"></label><div class="dash-form-grid"><label>Data<input name="date" type="date" required value="${esc(meeting?.date||dashToday())}"></label><label>Horário<input name="time" type="time" required value="${esc(meeting?.time||'09:00')}"></label></div><div class="dash-form-grid"><label>Duração (minutos)<input name="duration" type="number" min="15" max="480" step="15" required value="${esc(meeting?.duration||60)}"></label><label>Responsável<input name="responsible" required maxlength="80" value="${esc(meeting?.responsible)}" placeholder="Quem conduz a reunião"></label></div><label>Cliente<select name="clientId">${dashClientOptions(meeting?.clientId)}</select></label><label>Participantes<input name="participants" maxlength="250" value="${esc(meeting?.participants)}" placeholder="Nomes ou e-mails"></label><label>Local ou link<input name="location" maxlength="250" value="${esc(meeting?.location)}" placeholder="Sala de reunião ou https://..."></label><label>Pauta / observações<textarea name="notes" rows="3">${esc(meeting?.notes)}</textarea></label>`;if(kind==='nps')content=`<label>Cliente<select name="clientId" required><option value="">Selecione o cliente</option>${dashClients().map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label>Nota de 0 a 10<input name="score" type="number" min="0" max="10" required></label><label>Comentário<input name="comment" maxlength="500" placeholder="Comentário do cliente (opcional)"></label>`;if(!content)return;const root=document.createElement('div');root.className='dash-dialog';root.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${kind}"><h3>${{goal:'Editar meta',task:task?'Editar tarefa':'Criar tarefa',nps:'Registrar NPS',meeting:meeting?'Editar reunião':'Agendar reunião'}[kind]}</h3><form id="dash-form">${content}<div class="actions"><button type="button" class="dash-btn" data-dash="close">Cancelar</button><button class="dash-btn orange" type="submit">Salvar</button></div></form></div>`;document.body.append(root);root.querySelector('input,select')?.focus()}
function dashOverview(title,items,fn,empty){document.querySelector('.dash-dialog')?.remove();const root=document.createElement('div');root.className='dash-dialog';root.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3>${dashList(items,fn,empty)}<div class="actions"><button class="dash-btn" data-dash="close">Fechar</button></div></div>`;document.body.append(root)}
function dashAction(action,id){if(['goal','task','nps','meeting'].includes(action)){dashOpen(action);return}if(action==='edit-task'){dashOpen('task',id);return}if(action==='edit-meeting'){dashOpen('meeting',id);return}if(action==='close'){document.querySelector('.dash-dialog')?.remove();return}if(action==='panels'){dashState.showPanels=!dashState.showPanels;renderDashboard();return}if(action==='client'){openModal('details',id);return}if(action==='finance'){menu.querySelector('[data-page="Clientes"]').click();return}if(action==='all-tasks'){menu.querySelector('[data-page="Kanban"]').click();return}if(action==='all-meetings'){dashOverview('Agenda de reuniões',dashState.meetings.filter(m=>!m.cancelled).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),dashMeetingRow,'Nenhuma reunião registrada');return}if(action==='products'||action==='content'){dashOverview(action==='products'?'Produtos':'Calendário',[],()=>'',action==='products'?'O cadastro de estoque ainda não está disponível.':'O calendário de conteúdos ainda não está disponível.');return}if(action==='complete'){const t=dashState.tasks.find(t=>t.id===id);if(t&&!t.done){t.done=true;t.status='Concluído';dashActivity('Tarefa concluída: '+t.title,t.clientId);renderDashboard()}return}if(action==='cancel-meeting'){const m=dashState.meetings.find(m=>m.id===id);if(m&&confirm('Cancelar esta reunião?')){m.cancelled=true;dashActivity('Reunião cancelada: '+m.title,m.clientId);document.querySelector('.dash-dialog')?.remove();renderDashboard()}return}if(action==='remove-reminder'){dashState.reminders=dashState.reminders.filter(r=>r.id!==id);dashActivity('Lembrete removido');renderDashboard();return}if(action==='diagnosis'){const v=dashValues();document.querySelector('#dash-diagnosis').innerHTML=`<p>Carteira ativa: ${dashClients().length} clientes · Receita estimada no período: ${dashCurrency(v.total)} · Tarefas pendentes: ${dashState.tasks.filter(t=>!t.done&&!t.archived).length} · Meta alcançada: ${Math.round(v.total/Math.max(1,dashState.target)*100)}%.</p>`}}
function dashSave(form){const f=Object.fromEntries(new FormData(form)),kind=dashState.dialog,id=dashState.editingId;if(kind==='goal'){dashState.target=Math.max(1,Number(f.value)||10000);dashActivity('Meta atualizada para '+dashCurrency(dashState.target))}else if(kind==='task'){const c=dashClients().find(c=>c.id===f.clientId),data={title:f.title.trim(),due:f.due,time:f.time,clientId:f.clientId,client:c?.name||'',responsible:f.responsible.trim(),notes:f.notes.trim(),status:'A Fazer',done:false,archived:false,createdAt:new Date().toISOString()},old=dashState.tasks.find(t=>t.id===id);if(old){Object.assign(old,{...data,status:old.status,done:old.done});dashActivity('Tarefa editada: '+data.title,data.clientId)}else{dashState.tasks.unshift({id:crypto.randomUUID(),...data});dashActivity('Tarefa criada: '+data.title,data.clientId)}}else if(kind==='meeting'){const data={title:f.title.trim(),date:f.date,time:f.time,duration:Number(f.duration),responsible:f.responsible.trim(),clientId:f.clientId,client:dashClients().find(c=>c.id===f.clientId)?.name||'',participants:f.participants.trim(),location:f.location.trim(),notes:f.notes.trim(),cancelled:false},old=dashState.meetings.find(m=>m.id===id);if(old){Object.assign(old,data);dashActivity('Reunião editada: '+data.title,data.clientId)}else{dashState.meetings.push({id:crypto.randomUUID(),...data});dashActivity('Reunião agendada: '+data.title+' · '+formatDate(data.date)+' às '+data.time,data.clientId)}}else if(kind==='nps'){dashState.nps.push({id:crypto.randomUUID(),clientId:f.clientId,score:Number(f.score),comment:f.comment.trim(),date:dashStamp()});dashActivity('NPS registrado para '+(dashClients().find(c=>c.id===f.clientId)?.name||'cliente'),f.clientId)}document.querySelector('.dash-dialog')?.remove();renderDashboard();toast('Registro atualizado nesta sessão.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-dash]');if(b)dashAction(b.dataset.dash,b.dataset.id);if(e.target.classList.contains('dash-dialog'))e.target.remove()});
document.addEventListener('submit',e=>{if(e.target.id==='reminder-form'){e.preventDefault();const v=String(new FormData(e.target).get('reminder')||'').trim();if(v){dashState.reminders.unshift({id:crypto.randomUUID(),text:v});dashActivity('Lembrete criado: '+v);renderDashboard()}return}if(e.target.id==='dash-form'){e.preventDefault();dashSave(e.target)}});
document.addEventListener('change',e=>{if(!['dash-range','dash-start','dash-end'].includes(e.target.id))return;if(e.target.id==='dash-range'){dashState.range=e.target.value;const now=new Date();if(e.target.value==='month')dashState.start=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;else if(e.target.value==='7'||e.target.value==='30'){const d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-(Number(e.target.value)-1));dashState.start=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}dashState.end=e.target.value==='custom'?dashState.end:dashToday()}else{dashState.range='custom';dashState.start=document.querySelector('#dash-start').value;dashState.end=document.querySelector('#dash-end').value}if(dashState.start&&dashState.end&&dashState.start>dashState.end){toast('A data inicial deve vir antes da data final.');return}renderDashboard()});
function dashTooltip(point){const tooltip=document.querySelector('#dash-chart-tooltip');if(!tooltip)return;tooltip.textContent=`${point.dataset.label} · ${point.dataset.value} — receita contratual estimada`;tooltip.hidden=false;const wrap=point.closest('.dash-chart-wrap'),rect=point.getBoundingClientRect(),outer=wrap.getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(outer.width-tooltip.offsetWidth-8,rect.left-outer.left))+'px';tooltip.style.top=Math.max(0,rect.top-outer.top-48)+'px'}
document.addEventListener('pointerover',e=>{const point=e.target.closest?.('.dash-chart-point');if(point)dashTooltip(point)});document.addEventListener('pointerout',e=>{if(e.target.closest?.('.dash-chart-point')){const tip=document.querySelector('#dash-chart-tooltip');if(tip)tip.hidden=true}});document.addEventListener('focusin',e=>{if(e.target.matches?.('.dash-chart-point'))dashTooltip(e.target)});document.addEventListener('focusout',e=>{if(e.target.matches?.('.dash-chart-point')){const tip=document.querySelector('#dash-chart-tooltip');if(tip)tip.hidden=true}});
